function capNineCompress(word: string): string {
  const out: string[] = [];
  let i = 0;
  while (i < word.length) {
    let j = i;
    while (j < word.length && word[j] === word[i]) j++;
    let len = j - i;
    while (len > 0) {
      const take = Math.min(9, len);
      out.push(take + word[i]);
      len -= take;
    }
    i = j;
  }
  return out.join("");
}

